"""Reuses persisted GPT/Solar results. Does not call any model."""
import hashlib,json,shutil,sys
from pathlib import Path
from quality_metrics import measure
ROOT=Path(__file__).resolve().parents[1];base=ROOT/'test-results/submission';out=ROOT/'release/public'
gold=json.loads((out/'expected.json').read_text());rows={}
for stage in ['baseline','improved']:
 folder=base/stage;revision=json.loads((folder/'revision.json').read_text());sources=json.loads((folder/'sources.json').read_text())
 result=measure(revision['payload']['items'],gold,sources);coverage=revision['payload']['coverage']
 result.update(model='solar-pro4',resolved_models=sorted({c.get('resolved_model','') for c in coverage}),calls=sum(len(c.get('calls',[])) for c in coverage),tokens=sum(c.get('usage',{}).get('total_tokens',0) for c in coverage),prompt_hashes=sorted({c.get('prompt_hash','') for c in coverage}))
 rows[stage]=result;(folder/'metrics.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
gpt=json.loads((base/'gpt-audit/metrics.json').read_text());usage=json.loads((base/'gpt-audit/usage.json').read_text());response=json.loads((base/'gpt-audit/response.json').read_text());gpt.update(model='gpt-5.4-mini',resolved_models=[response.get('model')],calls=1,tokens=usage['input_tokens']+usage['output_tokens']);rows['gpt_reference']=gpt
adjudication=json.loads((base/'gpt-audit/adjudication.json').read_text())
result={'sample_sha256':gold['sample_sha256'],'method':'7 synthetic documents; manual pre-authored 56 substring-presence checks; evidence substring validation; non-blind GPT reference audit','gpt_inference_requests':1,'gpt_response_sha256':hashlib.sha256((base/'gpt-audit/response.json').read_bytes()).hexdigest(),'gpt_usage':usage,'results':rows,'adjudication':adjudication,'e2e':json.loads((base/'improved/e2e.json').read_text()),'limits':['Synthetic development set, not held-out institutional data','Field inclusion score is not precision or universal semantic accuracy','GPT saw Solar output; reference audit is not blinded','Prompt improved on the same set; no claim of generalization gain']}
# Don't publish localhost URLs as a live demo link.
result['e2e'].pop('url',None)
(out/'quality-results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
lines=['# 업무바통 최종 품질 검토 · v1.0.0','','## 결론','','다운로드 샘플 7개를 실제 등록하여 Solar 분석 → 근거 확인 → 기한 수정 → 확정 → 후임자 인수 → 보고서 다운로드를 검증했습니다. GPT-5.4-mini는 최종 기능 검증 후 추론 요청을 **1회**만 실행했고, 그 응답을 그대로 재사용했습니다.','','## 동일 샘플 비교','','| 항목 | Solar 개선 전 | GPT 참조 결과 | Solar 개선 후 |','|---|---:|---:|---:|']
for label,key in [('찾은 업무 수','matched_tasks'),('수동 정답표 값 조건 통과 (총 56)','field_passed'),('원문 인용 수','quotes'),('원문 불일치 인용','invalid_quotes'),('실제 문서 추출/검토 호출','calls'),('사용 토큰','tokens')]:lines.append('| '+label+' | '+' | '.join(str(rows[k][key]) for k in ['baseline','gpt_reference','improved'])+' |')
lines+=['','세 결과 모두 기한 충돌을 보존하고, 협의 부서를 담당자로 오인하지 않았으며, 부분 완료를 전체 완료로 처리하지 않았습니다. 모델 출력의 세부 표현과 인용 개수는 달라질 수 있습니다.','','## GPT 지적을 그대로 적용하지 않은 이유','','GPT는 같은 업무의 문서 통합과 시설점검 상태의 복수 관측을 두 건의 MAJOR 문제로 분류했습니다. 원문·개별 근거·서버 판정에 대조한 결과, 두 건 모두 요구된 정상 통합 기능에 대한 오판으로 판단해 채택하지 않았습니다.','','- 사업계획의 11/20·11/25는 CONFLICT와 각각의 원문으로 보존됩니다. 최종 기한은 전임자가 확인합니다.','- 시설점검의 “점검 예정”과 “사전 점검 완료”는 별도 관측으로 보존되고 전체 완료로 판정되지 않습니다.','- 검증 모델의 의견을 자동 사실로 받아들이지 않고, 해당 계약을 회귀 테스트로 고정했습니다.','','## 반영한 Solar 프롬프트 개선','','1. 현재 문서·해당 업무 섹션의 근거만 사용하고 다른 문서/업무의 담당·연락처·실적을 임의 보충하지 않도록 명시.','2. “사전 점검”, “접수만”, “초안” 같은 단계 한정어를 원문 인용에 유지.','3. 블록 사이의 표현을 합성 인용으로 만들지 않도록 명시하고, 문서 간 통합은 서버 책임임을 분리.','','개선 전에도 정답표 조건을 모두 만족했으므로, 개선 후 정확도가 수치상 향상됐다고 주장하지 않습니다. 같은 개발용 합성 셋에서 정상 기능을 유지하며 지침을 명확히 한 결과입니다.','','## 비용·재사용·공유 한도','','GPT 요청 모델: `gpt-5.4-mini`, 응답 모델: `'+str(response.get('model'))+'`. 입력 '+str(usage['input_tokens'])+' / 출력 '+str(usage['output_tokens'])+' 토큰, 합계 '+str(gpt['tokens'])+' 토큰. Standard 단가에 따른 보수적 비용 추정은 $'+str(usage['cost_usd'])+'이며 공급자 청구서가 아닙니다.','','PoC7·10·11이 공유하는 일일 mini 토큰 원장에 PoC7 기존 검증 클라이언트로 사전 예약·사후 정산했습니다. 실제 수혜 프로젝트는 `poc13-handover`, 작업은 `final-quality-audit`로 사용량 서비스에 기록했습니다. 다른 PoC 코드·설정·컨테이너는 변경하지 않았습니다. 요청·응답·해시·정산 파일과 단독 실행 잠금을 보존하며 자동 재호출은 없습니다.','','## E2E 확인','','- 직접 다운로드한 ZIP과 정답표에 기록한 SHA-256이 일치.','- 7개 파일 등록, 실제 Solar 문서별 분석, 원문 근거 확인.','- 전임자가 기한을 2026-11-27로 수정하고 근거·사유 보존.','- 양측 동일 확정본, 후임자 인수 확인, 질문에서 확정 기한 우선.','- HTML·MD·DOCX 실제 다운로드와 A4 PDF 출력.','- 데스크톱·모바일 열람, JavaScript 오류 0건.','','## 평가의 한계','','56개 값 조건은 사람이 미리 작성한 정답값이 출력에 포함되는지 검사합니다. 이는 정밀도·실제 업무 정확도 100%를 뜻하지 않습니다. 인용의 문자 일치도 의미 정확성과 다릅니다. GPT는 Solar 결과를 함께 본 비맹검 참조 검토이며, 별도 기관 문서·독립 홀드아웃 평가나 사람 심사 결과가 아닙니다. 최종 인수인계는 담당자가 원문과 현실 업무 상태를 확인해야 합니다.','','영상은 사용자 요청에 따라 이번 작업에서 제작하지 않았습니다. 참가 정보·공공 GitLab·공모 접수는 미정입니다.','','[기계 판독 결과](quality-results.json) · [샘플 정답표](expected.json) · [OpenAI 공식 모델 문서](https://developers.openai.com/api/docs/models/gpt-5.4-mini)']
text='\n'.join(lines)+'\n';(out/'quality-report.md').write_text(text);(ROOT/'docs/submission/QUALITY_REPORT.md').write_text(text)
